mapper.select:
select node_id, group_id, app_id, event_id, datetime, total, delta, aux
from appmon_event_count_last
where node_id = #{nodeId} and app_id = #{appId} and event_id = #{eventId}

choose.when:
insert into appmon_event_count_last (node_id, group_id, app_id, event_id, datetime, total, delta, aux)
values (#{nodeId}, #{groupId}, #{appId}, #{eventId}, #{datetime}, #{total}, #{delta}, #{aux})
on duplicate key update group_id = #{groupId}, datetime = #{datetime}, total = #{total}, delta = #{delta}, aux = #{aux}

insert into appmon_event_count (node_id, group_id, app_id, event_id, datetime, total, delta, aux)
values (#{nodeId}, #{groupId}, #{appId}, #{eventId}, #{datetime}, #{total}, #{delta}, #{aux})
on duplicate key update group_id = #{groupId}, total = #{total}, delta = #{delta}, aux = #{aux}

select datetime, delta, aux
from (
    select datetime, delta, aux
    from appmon_event_count
    where node_id = #{nodeId} and app_id = #{appId} and event_id = #{eventId}

        and datetime < #{dateOffset}

    order by 1 desc
)
where rownum <= 100
order by 1

choose.otherwise:
select datetime, delta, aux
from (
    select datetime, delta, aux
    from appmon_event_count
    where node_id = #{nodeId} and app_id = #{appId} and event_id = #{eventId}

        and datetime < #{dateOffset}

    order by 1 desc
    limit 100
) as x
order by 1

choose.when:
select datetime, delta, aux
from (
    select datetime, sum(delta) as delta, sum(aux) as aux
    from appmon_event_count
    where group_id = #{groupId} and app_id = #{appId} and event_id = #{eventId}

        and datetime < #{dateOffset}

    group by datetime
    order by 1 desc
)
where rownum <= 100
order by 1

