choose.when:
select datetime, delta, aux
from (
    select min(datetime) as datetime, sum(delta) as delta, case when #{eventId} = 'session' then max(aux) else sum(aux) end as aux
    from (
        select datetime, delta, aux
        from appmon_event_count_hourly
        where node_id = #{nodeId} and app_id = #{appId} and event_id = #{eventId}

            and datetime < #{dateOffset}

        order by datetime desc
    )
    where rownum <= 3000
    group by trunc(datetime + #{zoneOffset} / 86400.0)
    order by 1 desc
)
where rownum <= 100
order by 1

select datetime, delta, aux
from (
    select min(datetime) as datetime, sum(delta) as delta, case when #{eventId} = 'session' then max(aux) else sum(aux) end as aux
    from (
        select datetime, delta, aux
        from appmon_event_count_hourly
        where node_id = #{nodeId} and app_id = #{appId} and event_id = #{eventId}

            and datetime < #{dateOffset}

        order by datetime desc
        limit 3000
    ) as raw
    group by date(date_add(datetime, interval #{zoneOffset} second))
    order by 1 desc
    limit 100
) as x
order by 1

